import type { Page } from '@playwright/test';

export async function sortOwnersByCity(page: Page) {
    const sortRequest = page.waitForResponse(
        response => response.url().includes('/petclinic/api/owners') && response.url().includes('sort=city')
    );
    await page.locator("#sortByCity").click();
    await sortRequest;
    await page.waitForLoadState('networkidle');
}

export async function readOwnerCityColumn(page: Page) {
    return page.locator("#ownersTable table > tbody > tr > td:nth-child(3)").allInnerTexts();
}

export async function fillOwnerCity(page: Page, city: string) {
    await page.locator("#city").waitFor({ state: 'visible', timeout: 10000 });
    await page.locator("#city").fill(city);
}
